cards.css:
body { padding: 40px; }

.kotak {
  width: 100px;
  height: 50px;
  background: lightblue;
  border: 2px solid blue;
  margin-bottom: 20px;
  text-align: center;
  line-height: 50px;
}

.geser {
  transform: translate(50px, 0);
}

.besar {
  transform: scale(1.5);
}

.putar {
  transform: rotate(15deg);
}

